SELECT COUNT(*) FROM badges as b, comments as c, votes as v, users as u WHERE u.Id = c.UserId AND u.Id = b.UserId AND u.Id = v.UserId AND b."Date"<=CAST('2014-08-19 10:32:13' AS TIMESTAMP) AND c.Score=1 AND c.CreationDate>=CAST('2010-08-27 14:12:07' AS TIMESTAMP) AND v.VoteTypeId=5 AND v.CreationDate>=CAST('2010-07-19 00:00:00' AS TIMESTAMP) AND v.CreationDate<=CAST('2014-09-13 00:00:00' AS TIMESTAMP)
